    biography: "Nana Adjoa Serwaa Boatemaa is an emerging leader, creative communicator and youth advocate pursuing a Bachelor of Arts in Communication Design at Kwame Nkrumah University of Science and Technology (KNUST). Her educational journey began at Tiny Towers and Bethel Hill Academy in Cantonments, continued through Junior High School in Teshie, and progressed to St. Louis Senior High School, where she developed discipline, confidence and a strong academic foundation. As a final-year Communication Design student, she continues to develop her skills in visual storytelling, strategic design, critical thinking and purposeful communication across diverse audiences and media. Her leadership journey includes serving as Deputy Executive Judicial Chair, a member of the Women's Commission and Assistant Media Representative within PENSA KNUST. These roles have strengthened her experience in organisational administration, teamwork and professional communication. Beyond the classroom, she has volunteered at the Success Africa Summit and participated as a delegate at the 3AI Africa Summit. She has also represented her department in university-level competitions, demonstrating her willingness to embrace challenges and pursue creative excellence. As a Member of Parliament for La Dade-Kotopon under Youth Parliament Ghana, she is committed to public service, youth empowerment, civic responsibility and using design and communication to contribute to positive social change.",
