    biography: "JESSEY KOFI ADAMS, popularly known as CJAY, is a Ghanaian student leader and emerging public-service professional committed to youth development, community service and accountable leadership. As President of Liberty Hall at Kumasi Technical University during the 2024–2025 period, he led efforts to strengthen campus security through the installation of CCTV cameras, restore reliable water access by facilitating the installation of a missing pump, and advocate for improved student facilities. Through stakeholder engagement, problem-solving and responsive representation, he demonstrated a practical commitment to addressing community needs. Guided by the principle 'Impact, Not Position,' he advocates youth empowerment, good governance, civic participation and Ghana's national development.",
    vision: "To promote accountable leadership, youth empowerment and community development through practical solutions and meaningful representation.",
    plans: "To encourage youth participation in decision-making, advocate improved educational and student facilities, promote community service and support initiatives that strengthen accountability and development in the Obuasi East Constituency.",
