    education: "Kwame Nkrumah University of Science and Technology (KNUST) — Bachelor of Science (BSc) in Statistics, final year, specialising in Quantitative Analysis; University of the People — Bachelor of Science (BSc) in Computer Science, third year, with Honors List distinction.",
    profession: "Aspiring AI/ML Data Architect, Software Engineer, Author, Agricultural Technology Innovator and Agricultural Operations Manager",
    experience: "Experience in youth leadership, statistical analysis, software development, agricultural technology innovation, research, academic outreach and systems architecture. Elected Member of Youth Parliament for Ahafo Ano South West; Student Counselor, Bimoba Students' Union (BISU KNUST), 2024–2025 academic year; Delegation Leader, Climate & Africa Series (CAS Ghana / African Change Series), 2025; Executive Committee Member and Active Fellow, Young Professionals and Youth Coalition (YPYC-KNUST); Technical Delegate, University Information Technology Services (UITS) Track and KNUST E-Learning International Conference (ELIC); Bible Study Coordinator, Zarantinga Baptist Church, 2018–2019. He is also developing Agri-Sentio and AgricPioneers, agricultural technology initiatives focused on data-driven insights.",
    biography: "MATEIYENDOU KOMBAT is an elected Member of Youth Parliament representing the Ahafo Ano South West Constituency in the Ashanti Region under Youth Parliament Ghana. He is an aspiring AI/ML Data Architect, software engineer, author, agricultural technology innovator and youth leader dedicated to sustainable socio-economic development, digital transformation and educational advancement. He is concurrently pursuing a Bachelor of Science in Statistics, specialising in Quantitative Analysis, at Kwame Nkrumah University of Science and Technology (KNUST), where he is in his final year, and a Bachelor of Science in Computer Science at the University of the People, where he is in his third year with Honors List distinction. He is authoring three interdisciplinary manuscripts spanning engineering, applied statistics, resource management and humanities. Driven by empirical problem-solving, he leads the conceptualisation and development of Agri-Sentio, an agricultural telemetry and sensor-ingestion system, alongside AgricPioneers. These initiatives aim to equip local agricultural communities with actionable, data-driven insights. In his parliamentary role, he prioritises youth empowerment, academic outreach to secondary schools, sustainable agricultural frameworks and collaboration with municipal and traditional authorities across Ahafo Ano South West.",
    vision: "To advance youth empowerment, digital transformation, educational development and sustainable agriculture through evidence-based innovation, research and collaborative governance.",
    plans: "To promote youth empowerment programmes, support academic outreach initiatives for secondary schools, encourage technology adoption in agriculture, develop data-driven solutions for local agrarian communities and foster collaboration with municipal and traditional authorities in Ahafo Ano South West.",
    contribution: "Contributes to youth representation, academic engagement, software development and agricultural technology innovation. Through Agri-Sentio and AgricPioneers, he is developing technology initiatives intended to provide agricultural communities with data-driven insights. His work also spans interdisciplinary writing, statistical analysis and youth leadership.",
    currentActivities: "Serving as Youth Member of Parliament for Ahafo Ano South West; pursuing Statistics at KNUST and Computer Science at the University of the People; developing Agri-Sentio and AgricPioneers; and authoring three interdisciplinary manuscripts.",
    leadershipExperience: "Elected Member of Youth Parliament, Ahafo Ano South West Constituency; Student Counselor, Bimoba Students' Union (BISU KNUST), 2024–2025 academic year; Delegation Leader, Climate & Africa Series (CAS Ghana / African Change Series), 2025; Executive Committee Member and Active Fellow, Young Professionals and Youth Coalition (YPYC-KNUST); Technical Delegate, University Information Technology Services (UITS) Track and KNUST E-Learning International Conference (ELIC); Bible Study Coordinator, Zarantinga Baptist Church, 2018–2019.",
