    experience: "Experience in student leadership, research coordination, academic programmes, health outreach and community needs assessment. Served as President of the Physician Assistant Student Association of Ghana (PASAG), University of Cape Coast Chapter; Head of the Research Committee of the SRC Executives Committee; and committee member for academic and health outreach programmes. Also participated in student representative initiatives at the University of Cape Coast. Has led and participated in research and needs assessment projects, including community needs assessments in Kwaboadi and surrounding communities.",
    biography: "ISMAILA EGYIR is a young, passionate and service-oriented youth from Gomoa Eshiem in the Central Region of Ghana. He is a member of Youth Parliament Ghana representing the Gomoa West Constituency. He is committed to youth leadership, healthcare, community development and public service. He completed his basic education at Gomoa Eshiem D/A JHS in 2014 and his secondary education in General Science at St. Andrews SHS in 2021. He is currently a Level 400 student pursuing a Bachelor of Science in Physician Assistant Studies at the University of Cape Coast, School of Medical Sciences, with expected completion in 2027. His leadership experience includes serving as President of the Physician Assistant Student Association of Ghana (PASAG), University of Cape Coast Chapter, and Head of the Research Committee of the SRC Executives Committee, where he contributed to research, data collection and academic programmes aimed at student welfare. As a Physician Assistant student undertaking clinical clerkship, he is developing practical knowledge in clinical medicine, with particular interests in Paediatrics and Child Health, Public Health and Community Medicine. He is also involved in health education, youth mentorship and community health outreach programmes in Gomoa and its environs. Through research and community needs assessment projects, including work in Kwaboadi and surrounding communities, he seeks to contribute to identifying local challenges and supporting practical solutions. As a youth parliamentarian, he is committed to promoting responsible youth leadership, healthcare awareness, community engagement and sustainable development.",
