    plans: "To encourage health education and community health outreach; promote youth mentorship and leadership development; support awareness of child health and public health issues; engage community stakeholders to identify local needs; encourage evidence-based approaches to community development; and advocate for initiatives that improve the welfare of young people and residents of Gomoa West.",
    contribution: "Contributes to student leadership, research coordination, academic programmes, health outreach and community needs assessment. Through his involvement in student governance and community health initiatives, he seeks to promote health education, youth mentorship and practical responses to community challenges.",
    currentActivities: "Serving as a Member of Youth Parliament Ghana for Gomoa West Constituency; undertaking Level 400 clinical clerkship in Physician Assistant Studies at the University of Cape Coast School of Medical Sciences; and maintaining interests in health education, community outreach, youth mentorship and public health.",
    leadershipExperience: "President, Physician Assistant Student Association of Ghana (PASAG), University of Cape Coast Chapter; Head of the Research Committee, SRC Executives Committee; Committee Member, Academic and Health Outreach Programs; Member, Student Representative Initiatives, University of Cape Coast.",
    professionalExperience: "Physician Assistant Student undertaking clinical clerkship at the University of Cape Coast School of Medical Sciences; student research and needs assessment activities; participation in community health outreach, health education and academic programmes.",
    focusAreas: "Youth Leadership, Healthcare, Paediatrics and Child Health, Public Health, Community Medicine, Health Education, Community Health Outreach, Youth Mentorship, Research, Student Welfare, Evidence-Based Development and Community Engagement",
