    biography: "UMM-KHAIRA AFRIYIE is a Ghanaian youth leader, aspiring chemical scientist and entrepreneur with interests in youth empowerment, scientific innovation and sustainable development. She represents the Asante Mampong Constituency in Youth Parliament Ghana. She completed a Bachelor of Science degree in Chemical Science and Technology at the University for Development Studies (UDS) between 2023 and 2026. Alongside her academic pursuits, she gained experience in student governance and organisational service, serving as Treasurer of the Department of Chemical Sciences, Electoral Commission Secretary of the Faculty of Physical Sciences, Electoral Commission Treasurer of the Physical Sciences Students Association, Obaa Panin of the Asante Regional Student Association and Treasurer of the Tertiary Education Institutions Network. These responsibilities strengthened her interests in leadership, accountability, teamwork and administration. She is also the Co-founder and Managing Director of VITAYAM Nutri Foods, an emerging food innovation initiative exploring creative and technological approaches to extending the shelf life of locally produced tubers, including yam. Her entrepreneurial interests reflect a commitment to food preservation, agricultural value addition and innovation-driven opportunities. Through Youth Parliament Ghana, she seeks to encourage meaningful youth participation, constructive policy discussions and initiatives that reflect the aspirations of young people. Her broader vision is to promote a generation that is informed, innovative, responsible and actively involved in community and national development.",
