    education: "Accra Technical University (ATU) — Higher National Diploma (HND) in Automobile Engineering, completed; Bachelor of Technology (BTech) in Automobile Engineering, currently Year 4 / Level 400. Biriwa Training Institute — previous institution, where he served in student leadership roles.",
    profession: "Automobile Engineering Student, Student Leader, Youth Advocate and Public Servant",
    experience: "Experience in student governance, electoral administration, cadet training, student association activities and youth representation. Currently serves as SRC Part-Time President at Accra Technical University for the 2026/2027 academic year. Previously served as Electoral Commissioner for the Faculty of Engineering at ATU, Cadet Physical Training Officer and Second-in-Command within the ATU Air Force Cadets, Assistant Compound Overseer at Biriwa Training Institute, and Organizer for the Ghana Muslim Students Association at Biriwa Training Institute. Recipient of the Most Hardworking Cadet Award.",
    biography: "OMAR SULLEY BIN, popularly known as Officer Moyole and associated with the slogan “Kaashe Gbeyei — Don’t Be Afraid,” is a youth leader, engineering student, student representative and community-oriented public servant committed to leadership, education, discipline and national development. He serves as Youth Member of Parliament for the Okaikwei Central Constituency under Youth Parliament Ghana, following his election or appointment on 5 September 2026. Through this role, he seeks to promote youth empowerment, responsible leadership, civic participation and meaningful representation of issues affecting young people. Hon. Omar has completed a Higher National Diploma in Automobile Engineering at Accra Technical University (ATU) and is currently pursuing a Bachelor of Technology in Automobile Engineering at the same institution, where he is in Year 4 / Level 400. His technical education has strengthened his interest in engineering, innovation, practical problem-solving and technical skills development. Beyond his academic pursuits, he serves as SRC Part-Time President of Accra Technical University for the 2026/2027 academic year, advocating for part-time students' welfare, academic support and representation. His leadership experience also includes serving as Electoral Commissioner for the Faculty of Engineering at ATU, Cadet Physical Training Officer and Second-in-Command within the ATU Air Force Cadets, Assistant Compound Overseer at Biriwa Training Institute, and Organizer for the Ghana Muslim Students Association at Biriwa Training Institute. He has also received the Most Hardworking Cadet Award in recognition of his dedication and participation in cadet activities. Hon. Omar believes leadership involves accepting responsibility, listening to people, creating opportunities and delivering meaningful results. Guided by humility, integrity, accountability and perseverance, he seeks to empower young people to become confident, responsible and active contributors to community development and national progress.",
    vision: "To empower young people to become confident, responsible and innovative contributors to community development and national progress through effective representation, education, discipline and service.",
    plans: "To promote youth participation in governance and civic education; advocate for student welfare and improved academic support for part-time students; encourage technical and vocational education and practical skills development; support leadership and discipline among young people; strengthen engagement between youth representatives and their communities; and promote accountability, teamwork and community service.",
    contribution: "Contributes to student representation, electoral administration, cadet training, student association activities and youth advocacy. Through his role as SRC Part-Time President, he advocates for part-time students' interests and welfare. His parliamentary role provides a platform to engage with youth concerns and promote responsible leadership, civic participation and community development.",
    currentActivities: "Serving as Youth Member of Parliament for Okaikwei Central Constituency; serving as SRC Part-Time President at Accra Technical University for the 2026/2027 academic year; pursuing a BTech in Automobile Engineering at ATU; and participating in student leadership and youth development activities.",
    leadershipExperience: "SRC Part-Time President, Accra Technical University, 2026/2027 academic year; Youth Member of Parliament, Okaikwei Central Constituency, Youth Parliament Ghana; Cadet Physical Training Officer and Second-in-Command, ATU Air Force Cadets; Electoral Commissioner, Faculty of Engineering, ATU; Assistant Compound Overseer, Biriwa Training Institute; Organizer, Ghana Muslim Students Association, Biriwa Training Institute.",
