    biography: "IDDRISU HABIB is a Ghanaian youth leader and advocate for good governance, youth empowerment and sustainable development from the Walewale Constituency in the North East Region of Ghana. He is committed to public service, economic development and promoting opportunities for young people. His leadership philosophy is grounded in integrity, accountability, inclusiveness and representing the interests of the youth. He was elected Youth Member of Parliament for the Walewale Constituency in 2026. Before his election, he served as North East Regional Youth Public Relations Officer at the beginning of 2026, gaining experience in communication, youth engagement and regional representation. At the University for Development Studies (UDS), Tamale, where he gained admission in 2024, he is pursuing a Bachelor of Science degree in Economics. His academic interests include economic development, resource allocation and the responsible management of scarce resources to address societal needs. His student leadership experience includes serving as Central Deputy Speaker of the UDS SRC Parliament, Member of the Students' Parliament from 2024 to 2025, Minority Chief Whip from 2025 to 2026 and Minority Leader from 2026 to 2027. He also serves as Treasurer of the School of Economics and Secretary of Union Hall for the 2026–2027 academic year. His earlier leadership roles include Senior Vice Prefect at primary school, Senior Boys' Prefect at Zangu Vuga Junior High School and Chief Imam of the Ghana Muslim Students Association at Bongo Senior High School from 2022 to 2023. His leadership and participation in student governance have earned him recognition as SRC Student Leader of the Year, School of Economics Gentleman of the Year and School of Economics Most Politician of the Year for the 2025–2026 period. Through Youth Parliament Ghana, he seeks to promote youth participation in governance, civic engagement, inclusive decision-making and community development. He aspires to apply his academic knowledge and leadership experience to public service and national development.",
